    public static class Token {
        private String token;

        public Token(String token) {
            this.token = token;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (o == null || getClass() != o.getClass()) return false;
            Token token = (Token) o;
            return Objects.equals(token.token, this.token);
        }

        @Override
        public int hashCode() {
            return Objects.hash(token);
        }
    }

    public static class Parser {
        private String[] input;

        public Parser(String[] input) {
            this.input = input;
        }

        public boolean hasNextToken() {
            if (input == null || input.length == 0) {
                return false;
            }
            for (int i = 0; i < input.length - 1; i++) {
                if (isDigit(input[i]) && isDigit(input[i + 1])) {
                    return true;
                }
            }
            return false;
        }

        public Token parseToken() {
            if (!hasNextToken()) {
                throw new RuntimeException("No more tokens");
            }
            String token = input[input.length - 1];
            int index = token.lastIndexOf(' ');
            if (index != -1) {
                return new Token(token.substring(0, index));
            } else {
                return new Token(token);
            }
        }

        public boolean isDigit(char c) {
            return Character.isDigit(c);
        }
    }

    public static class ParserResult<T> {
        private T result;

        public T getResult() {
            return result;
        }

        public void setResult(T result) {
            this.result = result;
        }

        @Override
        public String toString() {
            return "ParserResult{" +
                    "result=" + result +
                    '}';
        }
    }

    public static class ParserError extends RuntimeException {
        public ParserError(String message) {
            super(message);
        }
    }

    public static <T> void parseGrammar(Parser parser, T element) throws ParserError {
        if (element instanceof String) {
            parser.result = new Token((String) element);
        } else if (!(element instanceof List)) {
            throw new ParserError("Expected a string");
        } else {
            for (Object token : ((List<?>) element).asIterator()) {
                try {
                    parseGrammar(parser, token);
                } catch (ParserError e) {
                    System.out.println(e.getMessage());
                }
            }
        }
    }

    public static void main(String[] args) throws ParserError {
